import AVFoundation
import Testing
@testable import Closer

/// The sounds are generated by `scripts/generate-notification-sounds.py`. These tests make sure
/// every sound the app offers is in the bundle and is a file iOS accepts for notifications.
@MainActor
struct SoundPreviewPlayerTests {
    private let player = SoundPreviewPlayer(bundle: Bundle(for: PeopleViewModel.self))

    @Test func everyBundledSoundIsInTheAppBundle() {
        for sound in NotificationSound.bundled {
            #expect(player.url(for: sound) != nil, "\(sound.fileName ?? "") missing in the app bundle")
        }
    }

    @Test func theSystemDefaultHasNoFile() {
        #expect(player.url(for: .standard) == nil)
    }

    @Test(arguments: NotificationSound.bundled)
    func soundIsLinearPCMAndAtMostThirtySeconds(_ sound: NotificationSound) throws {
        let url = try #require(player.url(for: sound))
        let file = try AVAudioFile(forReading: url)
        let seconds = Double(file.length) / file.fileFormat.sampleRate
        #expect(seconds > 0.3)
        #expect(seconds <= 30)
        #expect(file.fileFormat.streamDescription.pointee.mFormatID == kAudioFormatLinearPCM)
    }

    @Test func playingAndStoppingDoesNotCrash() {
        player.play(.naehe)
        player.play(.standard)
        player.stop()
    }
}
